import os, sys
sys.path.insert(0, os.getcwd())

from flowpipe.node import Node
from flowpipe.graph import Graph
from flowpipe.plug import SubOutputPlug


def test_sub_outputs_created():
    @Node(outputs=["out.a", "out.b"])
    def MyNode():
        pass

    n = MyNode(graph=None)
    assert "out" in n.outputs
    assert set(n.outputs["out"]._sub_plugs) == {"a", "b"}
    assert isinstance(n.outputs["out"]["a"], SubOutputPlug)
    assert isinstance(n.outputs["out"]["b"], SubOutputPlug)


def test_all_outputs_names():
    @Node(outputs=["out.a", "out.b", "plain"])
    def MyNode():
        pass

    n = MyNode(graph=None)
    assert set(n.all_outputs()) == {"out", "out.a", "out.b", "plain"}
    assert set(n.outputs) == {"out", "plain"}
    assert not n.outputs["plain"]._sub_plugs


def test_parent_declared_explicitly_and_order():
    @Node(outputs=["out", "out.a", "out.b"])
    def MyNode():
        pass

    n = MyNode(graph=None)
    assert set(n.outputs["out"]._sub_plugs) == {"a", "b"}
    assert set(n.all_outputs()) == {"out", "out.a", "out.b"}


def test_sub_output_connect_and_value():
    @Node(outputs=["out.a", "out.b"])
    def Src():
        pass

    @Node(outputs=["res"])
    def Dst(x):
        return {"res": x}

    s = Src(graph=None)
    d = Dst(graph=None)
    s.outputs["out"]["a"] >> d.inputs["x"]
    s.outputs["out"]["a"].value = 5
    s.outputs["out"]["b"].value = 7
    assert d.inputs["x"].value == 5
    assert s.outputs["out"]["b"].value == 7


def test_repr_shows_sub_outputs():
    @Node(outputs=["out.a", "out.b"])
    def MyNode():
        pass

    n = MyNode(graph=None)
    text = n.node_repr()
    lines = text.split("\n")
    assert any(l.rstrip().endswith("%") and "out" in l and ".a" not in l for l in lines)
    assert any("out.a" in l and l.rstrip().endswith("o") for l in lines)
    assert any("out.b" in l and l.rstrip().endswith("o") for l in lines)

