import ast
import inspect
import os
import typing

from libcloudforensics.providers.gcp.internal import compute


def _find(method):
  for _, cls in inspect.getmembers(compute, inspect.isclass):
    if method in cls.__dict__:
      return cls.__dict__[method]
  raise AssertionError(method)


def _is_optional(hint):
  return type(None) in typing.get_args(hint)


def _hints(func):
  return typing.get_type_hints(func, vars(compute))


def test_create_disk_defaults_not_optional():
  hints = _hints(_find('CreateDiskFromSnapshot'))
  assert _is_optional(hints['disk_name'])
  assert not _is_optional(hints['disk_name_prefix'])
  assert not _is_optional(hints['disk_type'])


def test_analysis_vm_defaults_not_optional():
  hints = _hints(_find('GetOrCreateAnalysisVm'))
  for name in ('disk_type', 'cpu_cores', 'image_project', 'image_family'):
    assert not _is_optional(hints[name]), name
  assert _is_optional(hints['packages'])


def test_defaults_unchanged():
  sig = inspect.signature(_find('GetOrCreateAnalysisVm'))
  assert sig.parameters['disk_type'].default == 'pd-standard'
  assert sig.parameters['cpu_cores'].default == 4
  assert sig.parameters['packages'].default is None
  sig = inspect.signature(_find('CreateDiskFromSnapshot'))
  assert sig.parameters['disk_name_prefix'].default == ''


def _scan():
  root = os.path.join(os.getcwd(), 'libcloudforensics')
  bad_none = []
  bad_opt = []
  for dirpath, _, files in os.walk(root):
    for f in files:
      if not f.endswith('.py'):
        continue
      path = os.path.join(dirpath, f)
      with open(path, encoding='utf-8') as fh:
        tree = ast.parse(fh.read())
      for node in ast.walk(tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
          continue
        a = node.args
        pos = a.posonlyargs + a.args
        pairs = list(zip(pos[len(pos) - len(a.defaults):], a.defaults))
        pairs += [(k, d) for k, d in zip(a.kwonlyargs, a.kw_defaults) if d]
        for arg, d in pairs:
          if arg.annotation is None:
            continue
          text = ast.unparse(arg.annotation)
          isnone = isinstance(d, ast.Constant) and d.value is None
          where = '{0}:{1}:{2}'.format(path, node.name, arg.arg)
          if isnone and 'Optional' not in text and 'None' not in text \
              and 'Any' not in text:
            bad_none.append(where)
          if not isnone and text.replace("'", '').startswith('Optional'):
            bad_opt.append(where)
  return bad_none, bad_opt


def test_none_defaults_are_optional_everywhere():
  bad_none, _ = _scan()
  assert not bad_none, bad_none


def test_non_none_defaults_not_optional_everywhere():
  _, bad_opt = _scan()
  assert not bad_opt, bad_opt

import os, sys
