import lizard


def funcs(code):
    info = lizard.analyze_file.analyze_source_code("a.swift", code)
    return info.function_list


def names(code):
    return [f.name for f in funcs(code)]


def test_enum_case_named_get_not_function():
    code = '''
public enum HTTPMethod: String {
    case options = "OPTIONS"
    case get     = "GET"
    case head    = "HEAD"
}

class A {
    func foo(_ a: Int) {
        if a > 0 { return }
    }
}
'''
    assert names(code) == ["foo"]


def test_case_get_without_value():
    code = '''
enum M {
    case get
    case put
}
func bar() {
}
'''
    assert names(code) == ["bar"]


def test_variable_named_get_then_functions():
    code = '''
extension X {
    convenience init(baseURL url: URL?) {
        self.init(baseURL: url)
    }
    func foo(_ h: [String:String]) {
    }
    func bar(_ h: [String:String]) {
    }
}
'''
    code = "enum E {\n    case get = \"GET\"\n    case post = \"POST\"\n}\n" + code
    assert names(code) == ["init", "foo", "bar"]


def test_following_function_metrics_correct():
    code = '''
enum E {
    case get = "GET"
}
func foo(_ a: Int) {
    if a > 0 {
        return
    }
}
'''
    fl = funcs(code)
    assert len(fl) == 1
    assert fl[0].name == "foo"
    assert fl[0].cyclomatic_complexity == 2
    assert fl[0].parameter_count == 1


def test_real_getter_setter_still_detected():
    code = '''
class A {
    var x: Int {
        get {
            return 1
        }
        set {
            y = newValue
        }
    }
}
'''
    assert names(code) == ["get", "set"]
